    ctx.entry = '';
    paintPinDots();
    var d = e.data || {};
    if (e.status === 429 || d.retryAfterSeconds) {
      fetchPinState().catch(function () {});
      startPinWait(d.retryAfterSeconds || 30);
      return;
    }
