      if (e.status === 429 || d.retryAfterSeconds) { msg.textContent = 'Too many attempts \u2014 try again in ' + (d.retryAfterSeconds || 30) + ' seconds.'; return; }
      var rem = typeof d.attemptsRemaining === 'number' ? d.attemptsRemaining : null;
