    if (role === 'h') return '<div class="mass-sh">' + esc(ln) + '</div>';
    if (role === 'q') {
      var note = (i === 0 || roles.charAt(i - 1) !== 'q')
        ? '<div class="mass-quiet-note">(priest says quietly)</div>' : '';
      return note + '<div class="mass-line mass-quiet">' + esc(ln) + '</div>';
    }
