  function dropExample(f) {
    for (var i = 0; i < f.lines.length; i++) {
      if (f.lines[i].indexOf('May almighty God have mercy on us,') === 0) {
        return { lines: f.lines.slice(i), roles: f.roles.slice(i) };
      }
    }
    return f;
  }
