  view.innerHTML = '<div class="novsearchbar"><input type="search" id="nov-search" placeholder="Search novenas" value="' + esc(novenaSearchText) + '" autocomplete="off"></div>'
    + '<div id="nov-list">' + novenaCatalogListHtml(cat) + '</div>';
